        if dirnames:
            valid_subdirs = 0
            for d in dirnames:
                sub = os.path.join(dirname, d)
                try:
                    files = os.listdir(sub)
                except Exception:
                    continue
                if any(f.lower().endswith(image_ext) for f in files):
                    valid_subdirs += 1
            if valid_subdirs >= 2:
                return dirname
    return None

